using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (source-gen context)
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got typed metadata: {typedInfo.Type.Name} (JsonTypeInfo<{typedInfo.Type.Name}>)");

// Round-trip to prove it works
var forecast = new WeatherForecast { Date = new DateTime(2026, 7, 8), Summary = "Sunny", TemperatureC = 32 };
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
bool found = options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(WeatherForecast): found={found}, info is null={info is null}");

// Try a type NOT in our context — no exception, just returns false
bool foundUnknown = options.TryGetTypeInfo(typeof(Uri), out JsonTypeInfo? unknownInfo);
Console.WriteLine($"TryGetTypeInfo(Uri):             found={foundUnknown}, info is null={unknownInfo is null}");

// Records
public record WeatherForecast
{
    public DateTime Date { get; init; }
    public string? Summary { get; init; }
    public int TemperatureC { get; init; }
}

// Source-generated context that only knows about WeatherForecast
[JsonSerializable(typeof(WeatherForecast))]
internal partial class AppJsonContext : JsonSerializerContext { }
EOF

